    "Script": "RoleManagement = {
	init: async function (app, container) {
		app = app || session.app;
		container = container || $(".component[name=RoleManagement]");
		api.addToMetaCache([
			{
        "Name": "Core",
        "Types": [
            [meta[Core/Role]]
        ]
    }
		]);
		RoleManagement.setupRoleGrid(app, container);
	},

	setupRoleGrid: async function (app, container) {
		var config = {
			endpoint: "AppSecurity/Role",
			odataAppend: "?$filter=AppId eq " + app.Id,
			sort: {
				field: "Name",
				dir: "asc"
			},
            pageSize: 50
		};
		var ds = await model.getDatasource(config);
		var roleGrid = new GridWidget(container, ds);
		roleGrid.searchable = true;
		roleGrid.search = { fields: ["Name"] };
		roleGrid.groupable = false;
		roleGrid.toolbar = "<button name='createRole'><span class='k-icon k-i-add'></span>[resource_displayname[NewRole]]</button>";
		roleGrid.columns = [
			{
				field: "Name",
				title: "[resource_shortdisplayname[Name]]"
			}
		];
		roleGrid.commands.push({
			name: "[resource_displayname[save]]",
			icon: 'k-i-save',
			text: "[resource_displayname[save]]"
		});
		roleGrid.commands.push({
			name: "[resource_displayname[destroy]]",
			icon: 'k-i-delete',
			text: "[resource_displayname[delete]]"
		});
		roleGrid.detailTemplate = $("[name=roleDetails]").html();
		roleGrid.detailExpand = function (e) {
			RoleManagement.expandRole(e, app, roleGrid);
		};
		roleGrid.dataBound = function () {
			$("a[name=save]", roleGrid.gridElement)
				.off("click")
				.on("click", async (e) => await RoleManagement.save(e, roleGrid));
			
			$("a[name=destroy]", roleGrid.gridElement)
				.off("click")
				.on("click", async (e) => await RoleManagement.destroy(e, roleGrid));
		};
		await roleGrid.init();
		$("button[name=createRole]", roleGrid.gridElement)
			.off("click")
			.on("click", async (e) => await RoleManagement.createRole(e, app, roleGrid));
	},

	save: async function (e, grid) {
		e.preventDefault();
		var role = grid.dataItem($(e.currentTarget).closest("tr"));
		await role.save().then(() => { 
			notification.success("[resource_displayname[RoleSaved]]"); 
		}).catch((err) => {
			error(err);
		});
	},

	destroy: async function (e, grid) {
		e.preventDefault();
		var row = $(e.currentTarget).closest("tr");
		var role = grid.dataItem(row);
		grid.dataSource().remove(role);
		await api.destroy("AppSecurity/Role(" + role.Id + ")").then(() => { 
			notification.success("[resource_displayname[roledeleted]]"); 
		}).catch((err) => {
			error(err);
		})
	},

	expandRole: async function (e, app, grid, container) {
		var role = grid.dataItem(e.masterRow);
		var container = $(e.detailRow);
		if($(container).find(".component").length == 0) {
			$("[name=userGrid]", container).html($("[name=roleUserManagementComponent]").first().html());
			$("[name=privGrid]", container).html($("[name=rolePrivManagementComponent]").first().html());
			RoleUserManagement.init(app, $(".component[name=RoleUserManagement]", $("[name=userGrid]", container)), role);
			RolePrivManagement.init(app, $(".component[name=RolePrivManagement]", $("[name=privGrid]", container)), role);
		}
	},

	createRole: function (e, app, grid) {
        var newRole = {
            AppId: app.Id,
            Name: "[resource_displayname[newrole]]",
            Privs: ""
        };
		var args = {
			fields: [
				{
					field: "Name",
					title: "[resource_displayname[name]]"
				}
			],
			title: "[resource_displayname[newRole]]",
			data: newRole,
			confirm: "[resource_displayname[confirm]]",
			close: "[resource_displayname[close]]"
		};
		var addRoleDialog = new EditorDialog(args);
		addRoleDialog.events.confirm = async function () {
			newRole = addRoleDialog.data;//Remove all the kendo observable properties.
			await api.add("AppSecurity/Role", newRole).then(() => {
                notification.success('[resource_displayname[RoleCreated]]');
			    grid.refresh();
			    addRoleDialog.events.close();
            }).catch((err) => error(err));
		};
		addRoleDialog.init();
	}
}",
